    "/sessions/{id}/payments": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Initiate a payment
         * @description **Host-gated** — only the session host may initiate. Freezes the cart (`payment_pending`)
         *     and captures an immutable bill snapshot. Every accepted method — `cash`, `card`,
         *     `card_manual`, `digital`, `upi` — is created `requires_staff_confirmation` and resolved by a
         *     staff settle. `provider_pending` is NOT reachable from this endpoint; it remains a valid
         *     payment status for provider-created payments resolved by webhook. No fake success — the
         *     guest waits for a real `PAYMENT_COMPLETED`. Rate limited: sensitive 30/min per IP + 6/min
         *     per session.
         *
         *     Initiation is idempotent at two levels, and both answer **200** rather than 201: replaying
         *     the same `idempotency_key`, and initiating while the session already holds a non-terminal
         *     payment (that payment is returned as-is). Clients must treat 200 and 201 alike and read the
         *     payment from the body — only 201 means a new payment row was created.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path: {
                    id: string;
                };
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        /**
                         * Format: uuid
                         * @description Omit for session-level payments
                         */
                        order_id?: string | null;
                        amount: number;
                        /** @enum {string} */
                        method: "cash" | "card" | "digital" | "card_manual" | "upi";
                        /** @description Client-generated payment idempotency key scoped to the session and guest actor */
                        idempotency_key: string;
                        /** @description Provider payment reference for externally created provider payments */
                        provider_payment_ref?: string;
                        /**
                         * @description Optional promo code applied at the bill. Validated BEFORE any state mutation;
                         *     an invalid code is rejected without freezing the cart or burning the idempotency
                         *     key. The discount is folded into the immutable bill snapshot and the redemption is
                         *     recorded against the payment. The idempotency hash includes the promo code, so
                         *     changing the code on retry produces a fresh payment (regenerate the client key too).
                         */
                        promo_code?: string | null;
                        /** @description Guest phone in E.164 form. Required only when the promo enforces a per-guest limit (else `PROMO_PHONE_REQUIRED`). */
                        phone_e164?: string | null;
                    };
                };
            };
            responses: {
                /**
                 * @description Existing payment returned, nothing created. Either the `idempotency_key` was already
                 *     used for this session and actor (the original payment is replayed), or the session
                 *     already had a non-terminal payment, which is returned instead of opening a second one.
                 *     The body is the same `Payment` schema as 201.
                 */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Payment"];
                    };
                };
                /** @description Payment initiated (a new payment was created) */
                201: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Payment"];
                    };
                };
                400: components["responses"]["ValidationError"];
                401: components["responses"]["Unauthorized"];
                /** @description Caller is not the session host */
                403: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "code": "NOT_SESSION_HOST",
                         *       "message": "only the session host can initiate payment"
                         *     }
                         */
                        "application/json": components["schemas"]["APIError"];
                    };
                };
                /** @description Session not found, or promo code not valid/active (`PROMO_NOT_FOUND`) */
                404: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "code": "SESSION_NOT_FOUND",
                         *       "message": "session not found"
                         *     }
                         */
                        "application/json": components["schemas"]["APIError"];
                    };
                };
                /**
                 * @description An already-frozen cart / payment in progress no longer produces 409 — that case now
                 *     returns 200 with the existing payment. The remaining 409 paths are:
                 *     `IDEMPOTENCY_CONFLICT` (key reused with a different request body — note the hash
                 *     covers the promo code, so changing the code on retry must use a fresh key),
                 *     `IDEMPOTENCY_IN_PROGRESS` (a concurrent request holds the key),
                 *     `SESSION_CLOSED` (the session is in a state that can no longer take a payment), and
                 *     promo conflicts (`PROMO_EXHAUSTED`, `PROMO_ALREADY_USED`).
                 */
                409: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["APIError"];
                    };
                };
                /**
                 * @description `PAYMENT_AMOUNT_INVALID` — `amount` does not equal the authoritative bill total
                 *     (partial payment is not supported; the tolerance absorbs only sub-half-cent JSON
                 *     float representation). Or a promo present but not applicable:
                 *     `PROMO_PHONE_REQUIRED` (phone needed for a per-guest-limited promo) or
                 *     `MIN_ORDER_NOT_MET` (bill below the promo minimum).
                 */
                422: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "code": "PAYMENT_AMOUNT_INVALID",
                         *       "message": "payment amount must equal the full bill total"
                         *     }
                         */
                        "application/json": components["schemas"]["APIError"];
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
