    "/staff/auth": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Authenticate staff (10 RPM limit, fail-closed)
         * @description Authenticate with PIN plus either a numeric `branch_id` or a `branch_code`+`staff_code`.
         *     When `AUTH_STAFF_CODE_REQUIRED` (R4) is on, `branch_code`+`staff_code` are required.
         *     Repeated failures trigger a lockout (423).
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    /**
                     * @example {
                     *       "branch_id": 1,
                     *       "pin": "1234"
                     *     }
                     */
                    "application/json": {
                        /** @description Numeric branch id (legacy identifier path) */
                        branch_id?: number;
                        /** @description Branch code (required with staff_code under R4) */
                        branch_code?: string;
                        /** @description Per-staff code (required under R4) */
                        staff_code?: string;
                        pin: string;
                        device_name?: string;
                    };
                };
            };
            responses: {
                /** @description Authentication successful */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["StaffSession"];
                    };
                };
                400: components["responses"]["ValidationError"];
                /** @description Invalid credentials */
                401: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "code": "UNAUTHORIZED",
                         *       "message": "invalid credentials"
                         *     }
                         */
                        "application/json": components["schemas"]["APIError"];
                    };
                };
                /** @description Locked out after too many failed attempts */
                423: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "code": "AUTH_LOCKED_OUT",
                         *       "message": "too many failed attempts; try again later"
                         *     }
                         */
                        "application/json": components["schemas"]["APIError"];
                    };
                };
                429: components["responses"]["RateLimited"];
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
